            ['438', 'Монетизация без потери смысла', 'Четвёрка символизирует организацию, тройка — творческое выражение, восьмёрка — материальный результат. Число 438 напоминает, что заработок на своём деле возможен без обещаний невозможного и без отказа от честности.', 'Устойчивое дело с ясной ценностью.', 'Подстройка каждого слова под продажи.', 'Какую границу я не готов пересекать ради дохода?', 'Запиши три этических правила своего предложения.'],
            ['439', 'Поставить точку и освободить место', 'Четвёрка связана с завершением работы над формой, тройка — с созданием, девятка — с окончанием цикла. Число 439 напоминает, что незавершённый проект продолжает занимать внимание даже тогда, когда уже не приносит смысла.', 'Умение завершать или отпускать.', 'Вечное хранение проекта в статусе «почти готово».', 'Какое дело пора закончить либо сознательно закрыть?', 'Выбери для него один из двух исходов и назначь дату.']
  ];
  foreach ($entries as $entry) {
   [$number,$title,$symbolism,$light,$shadow,$question,$practice] = $entry;
   $record = NumberMeaning::query()->where('number',$number)->first();
   if (!$record) { continue; }
   $text = (string) $record->symbolism;
   $generated = str_starts_with($text,'Число '.$number.' можно использовать как повод для самонаблюдения.')
    || str_starts_with($text,'Иногда мы замечаем число в тот момент')
    || str_starts_with($text,'Представь это число не как указание судьбы')
    || str_starts_with($text,'Не нужно верить, что совпадение что-то предсказывает')
    || str_starts_with($text,'У чисел нет обязанности объяснять нашу жизнь')
    || str_starts_with($text,'Смысл здесь рождается не в цифрах')
    || str_starts_with($text,'Попробуй на мгновение оставить поиск тайного послания');
   if (!$generated) { continue; }
   $record->update(['title'=>$title,'symbolism'=>$symbolism,'light_side'=>$light,'shadow_side'=>$shadow,'reflection_question'=>$question,'practice'=>$practice]);
  }
 }
